    pub fn put_params(c: kayak_rt::data::DataAt<'static, Ctx>, names: Sexps, types: Sexps, mutable: bool, acc: Chars) -> Chars {
        if null_p(names) {
            acc
        } else {
            let name = {
                let tagcase_ = car(names);
                if Sexp::__is_Lst(tagcase_) {
                    let (xs, src_file, src_line, src_pos,) = Sexp::__Lst(tagcase_);
                    car(xs)
                } else {
                    let other = tagcase_;
                    other
                }
            };
            let acc = if mutable {
                put(str_lit!("mut "), acc)
            } else {
                acc
            };
            let acc = put(mangle(sym_name(name)), acc);
            let acc = put(str_lit!(": "), acc);
            let acc = put_type(c, car(types), acc);
            put_params(c, cdr(names), cdr(types), mutable, if null_p(cdr(names)) {
                acc
            } else {
                put(str_lit!(", "), acc)
            })
        }
    }

